UML = """classDiagram
    class House {
        +String address
        +bool standing
        +add_room(name, area) Room
        +demolish() void
    }
    class Room {
        +String name
        +float area
        +bool alive
    }
    House "1" *-- "*" Room : owns
"""


class Room:
    def __init__(self, house, name, area):
        if house is None:
            raise ValueError("A room needs a house")
        self.house = house
        self.name = name
        self.area = area

    @property
    def alive(self):
        return self.house.standing


class House:
    def __init__(self, address):
        self.address = address
        self.standing = True
        self._rooms = []

    @property
    def rooms(self):
        return tuple(self._rooms)

    @property
    def total_area(self):
        return sum(room.area for room in self._rooms)

    def add_room(self, name, area):
        if not self.standing:
            raise ValueError("The house was demolished")
        if any(room.name == name for room in self._rooms):
            raise ValueError("Duplicate room")
        if area <= 0:
            raise ValueError("Area must be positive")
        room = Room(self, name, area)
        self._rooms.append(room)
        return room

    def demolish(self):
        self.standing = False
        self._rooms.clear()
